package config

import (
	"os"
	"time"
)

type Config struct {
	ServerPort      string
	DatabaseURL     string
	ShutdownTimeout time.Duration
}

func Load() *Config {
	port := os.Getenv("SERVER_PORT")
	if port == "" {
		port = "8080"
	}
	return &Config{
		ServerPort:      port,
		DatabaseURL:     os.Getenv("DATABASE_URL"),
		ShutdownTimeout: 10 * time.Second,
	}
}

